(()=>{const keys=['spotsense-gto-v3.3','spotsense-v3','riverlab-morandi-v3','pokerTrainer_v1','spotsense-legacy-backup-v1','spotsense-preferences-v1','spotsense-models-v1'];let terms=[],config={},dialog,body,title;const ready=Promise.all([fetch('glossary.json').then(r=>r.json()),fetch('app-config.json').then(r=>r.json())]).then(([t,c])=>{terms=t;config=c}).catch(()=>{});const $=s=>document.querySelector(s),node=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e};function status(t){const e=$('#common-status');if(e)e.textContent=t}function backup(){const data=Object.fromEntries(keys.map(k=>[k,SSStorage.get(k)]).filter(x=>x[1]!==null)),u=URL.createObjectURL(new Blob([JSON.stringify({app:'SpotSense',version:3,data,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'})),a=node('a');a.href=u;a.download='SpotSense-backup.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),60000);status('已建立備份。')}async function restore(file){if(!file)return;try{if(file.size>15000000)throw Error('檔案過大');const b=JSON.parse(await file.text());if(b.app!=='SpotSense'||![1,2,3].includes(b.version)||!b.data)throw Error('格式不支援');const entries=Object.entries(b.data);if(!entries.length)throw Error('沒有紀錄');for(const[k,v]of entries){if(!keys.includes(k)||typeof v!=='string'||!JSON.parse(v))throw Error('欄位不合法')}if(!confirm('匯入將覆寫對應紀錄，請先備份。確定匯入？'))return;const old={};try{for(const[k]of entries)old[k]=SSStorage.get(k);for(const[k,v]of entries)if(!SSStorage.set(k,v))throw Error('寫入失敗')}catch(e){for(const[k,v]of Object.entries(old))v===null?SSStorage.remove(k):SSStorage.set(k,v);throw e}status('已匯入，重新載入後生效。')}catch(e){status('無法匯入：'+e.message)}}
async function open(p='resources',query=''){title.textContent='資源與設定';body.replaceChildren(node('p','載入中…'));if(!dialog.open)dialog.showModal();await ready;const names={resources:'資源與設定',glossary:'術語表',rules:'規則與閱讀指南',support:'支持SpotSense',feedback:'意見回饋',settings:'偏好設定',backup:'資料與備份',sources:'資料來源與限制',licenses:'第三方授權'};title.textContent=names[p]||names.resources;body.replaceChildren();if(p==='resources'){const g=node('div',undefined,'resource-grid');for(const[k,t]of Object.entries(names))if(!['resources','licenses'].includes(k)){const b=node('button',t,'resource-tile');b.dataset.common=k;g.append(b)}body.append(node('p','教學與訓練共用資源、設定與裝置紀錄。','muted'),g);return}if(p==='glossary'){const label=node('label',undefined,'field'),input=node('input'),count=node('p',undefined,'muted'),list=node('div');input.type='search';input.placeholder='搜尋中文、英文或縮寫';label.append(node('span','搜尋術語'),input);body.append(label,count,list);function draw(){const q=input.value.toLowerCase(),hits=terms.filter(t=>[t.id,t.name,t.en,t.description,t.learnNote,...(t.aliases||[])].join(' ').toLowerCase().includes(q));count.textContent=hits.length+' 個詞條';list.replaceChildren();for(const t of hits){const e=node('article',undefined,'term-card');e.append(node('h3',t.name),node('p',t.en,'term-en'),node('p',t.description));if(t.learnNote&&t.learnNote!==t.description){const d=node('details');d.append(node('summary','教學補充'),node('p',t.learnNote));e.append(d)}list.append(e)}}input.value=terms.find(t=>t.id===query)?.en||query;input.oninput=draw;draw();requestAnimationFrame(()=>input.focus({preventScroll:true}));return}if(p==='rules'){body.innerHTML='<p>本專案以六人桌無限注德州撲克概念為主；單挑順序與短籌碼參考會另外標示。</p><ol><li>從七張可用牌取最佳五張，必要時比較踢腳牌。</li><li>分清翻牌前或翻牌後，再確認行動順序。</li><li>無待跟注金額時Check/Bet；面對下注才有Fold/Call/合法Raise。</li><li>分清底池、跟注成本、剩餘籌碼及加注到的本街總額。</li><li>參考答案須連同人數、位置、尺寸、籌碼與來源閱讀。</li></ol><a class="link-button primary" href="learn.html?module=0">從基礎教學開始</a>';return}if(p==='support'){body.append(node('p','如果SpotSense對你有幫助，可以透過原專案的贊助頁支持維護。'));if(config.donateUrl?.startsWith('https://')){const a=node('a','前往贊助頁 ↗','link-button primary');a.href=config.donateUrl;a.target='_blank';a.rel='noopener noreferrer';body.append(a,node('p','將開啟外部網站，付款條件以該網站顯示為準。','muted'))}else body.append(node('p','目前未提供線上贊助連結。'));return}if(p==='feedback'){body.innerHTML='<p>留言及選填Email會交由Formspree處理，不自動附上手牌或學習紀錄。</p><form id="shared-feedback"><label class="field"><span>Email（選填）</span><input name="email" type="email"></label><label class="field"><span>類別</span><select name="category"><option value="bug">操作問題</option><option value="strategy">內容與策略</option><option value="feature">功能建議</option><option value="other">其他</option></select></label><label class="field"><span>內容</span><textarea name="message" rows="5" required maxlength="5000"></textarea></label><button class="primary">送出回饋</button></form><p id="common-status" role="status"></p>';const f=$('#shared-feedback');f.onsubmit=async e=>{e.preventDefault();if(!f.message.value.trim()){status('請輸入內容。');return}if(!config.feedbackEndpoint){status('目前未提供線上送出。');return}const b=f.querySelector('button');b.disabled=true;try{const r=await fetch(config.feedbackEndpoint,{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json'},body:JSON.stringify({subject:'SpotSense Feedback',email:f.email.value.trim(),category:f.category.value,message:f.message.value.trim()})});if(!r.ok)throw Error();f.reset();status('回饋已送出。')}catch{status('送出失敗，內容已保留。')}finally{b.disabled=false}};return}if(p==='settings'){body.innerHTML='<label class="field"><span>語言 / Language</span><select id="shared-language"></select></label><p class="muted">Train保留六語支援。本版Learn內容仍以繁體中文提供，其他語言教材翻譯尚未完成；語言偏好會保留。</p>';const select=$('#shared-language'),names={en:'English','zh-TW':'繁體中文','zh-CN':'简体中文',ja:'日本語',ko:'한국어',es:'Español'};for(const[c,t]of Object.entries(names)){const o=node('option',t);o.value=c;select.append(o)}select.value=SSLocale.get();select.onchange=()=>SSLocale.set(select.value);const d={soundEffectsEnabled:true,wrongAnswerFeedbackEnabled:true,...SSStorage.read('pokerTrainer_v1',{}).feedbackPreferences,...SSStorage.read('spotsense-preferences-v1',{})};for(const[k,t]of[['soundEffectsEnabled','發牌音效'],['wrongAnswerFeedbackEnabled','答錯提示']]){const l=node('label',undefined,'toggle-row'),i=node('input');i.type='checkbox';i.checked=!!d[k];l.append(node('span',t),i);body.append(l);i.onchange=()=>{const p=SSStorage.read('spotsense-preferences-v1',{});p[k]=i.checked;SSStorage.set('spotsense-preferences-v1',JSON.stringify(p));const raw=SSStorage.read('pokerTrainer_v1');if(raw){raw.feedbackPreferences={...raw.feedbackPreferences,...p};SSStorage.set('pokerTrainer_v1',JSON.stringify(raw))}if(typeof setFeedbackPreference==='function')setFeedbackPreference(k,i.checked)}}return}if(p==='backup'){body.innerHTML='<p>只在本機處理備份，不上傳伺服器。換裝置、瀏覽器或網域前，先匯出。</p><div class="button-row"><button id="shared-export" class="primary">匯出全部紀錄</button><button id="shared-import" class="secondary">匯入備份</button><input id="shared-file" type="file" accept=".json,application/json" hidden></div><p id="common-status" role="status"></p><hr><h3>清除本機紀錄</h3><p>包含教學、訓練及舊版封存，無法復原。</p><button id="shared-clear" class="secondary danger">清除全部紀錄</button>';$('#shared-export').onclick=backup;$('#shared-import').onclick=()=>$('#shared-file').click();$('#shared-file').onchange=e=>restore(e.target.files[0]);$('#shared-clear').onclick=()=>{if(confirm('清除全部紀錄與封存？無法復原，請先備份。')){keys.forEach(k=>SSStorage.remove(k));location.href='index.html'}};return}if(p==='licenses'){const pre=node('pre','載入中…','license-text');body.append(pre);try{pre.textContent=await fetch('THIRD_PARTY_NOTICES.md').then(r=>r.text())}catch{pre.textContent='請連線後重試。'}return}if(p==='sources'){body.innerHTML='<p>開池、防守及3-bet沿用原專案參考資料；無來源時才採明示內建基準。單挑SB不適用多人或ICM，未驗證翻牌後策略不計分。</p><p>教學完成與動作辨識率不代表完整實戰能力。本專案不是即時Solver。</p><ul><li>tyloo/poker-range-analyzer</li><li>AHTOOOXA/poker-charts</li><li>sweeterthancandy/CandyPoker</li></ul><button class="secondary" data-common="licenses">閱讀第三方授權</button>';return}}
window.SSCommon={open,backup};document.addEventListener('DOMContentLoaded',()=>{dialog=node('dialog',undefined,'shared-dialog');dialog.id='shared-dialog';dialog.setAttribute('aria-labelledby','shared-title');dialog.innerHTML='<div class="dialog-panel"><div class="dialog-head"><button class="secondary" data-common="resources">← 資源</button><h2 id="shared-title">資源與設定</h2><button id="shared-close" class="secondary" aria-label="關閉">×</button></div><div class="dialog-body" id="shared-body"></div></div>';document.body.append(dialog);title=$('#shared-title');body=$('#shared-body');$('#shared-close').onclick=()=>dialog.close();document.addEventListener('click',e=>{const b=e.target.closest('[data-common]');if(b){e.preventDefault();open(b.dataset.common)}});function grids(){document.querySelectorAll('.rg,.chart-grid,.range-editor-grid').forEach(g=>{if(g.closest('.grid-wrap'))return;const w=node('div',undefined,'grid-wrap'),sc=node('div',undefined,'grid-scroll'),b=node('button','放大矩陣／方便點選','secondary');sc.tabIndex=0;sc.setAttribute('role','region');sc.setAttribute('aria-label','範圍矩陣，可左右捲動');b.type='button';b.setAttribute('aria-expanded','false');g.before(w);w.append(b,sc);sc.append(g);b.onclick=()=>{const on=w.classList.toggle('grid-expanded');b.setAttribute('aria-expanded',String(on));b.textContent=on?'還原矩陣':'放大矩陣／方便點選'}})}grids();new MutationObserver(grids).observe(document.body,{subtree:true,childList:true});const p=new URLSearchParams(location.search).get('resource');if(p)open(p)});})();